css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .mosaico{display: flex; gap: 13px; flex-wrap: wrap;}
.mz .mosaico .mn{font-size: 19px; font-weight: 700; border: 1.5px solid var(--bosque); border-radius: 8px; padding: 7px 15px;}
.mz .pi-tabla{border-collapse: collapse; width: 100%;}
.mz .pi-tabla th,.mz .pi-tabla td{border: 1.5px solid var(--bosque);}
.mz .pi-tabla th{font-family: sans-serif; font-size: 13px; background: #f3f3f3; padding: 5px 0; width: 50%;}
.mz .pi-tabla td{height: 78px; vertical-align: top;}
.mz .vf-fila{display: flex; align-items: center; gap: 12px; font-size: 15px; font-weight: 600; margin-bottom: 9px;}
.mz .vf-fila .frase{flex: 1; line-height: 1.3;}
.mz .vf-opts{display: flex; gap: 10px; flex-shrink: 0;}
.mz .vf-opts .vf{width: 30px; height: 30px; border: 1.5px solid var(--bosque); border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 15px;}
.mz .prob{border: 1.5px solid var(--bosque); border-radius: 10px; padding: 11px 14px; font-size: 15px; font-weight: 600; line-height: 1.4;}
.mz .prob .linea-resp{border-bottom: 1.5px solid var(--bosque); height: 28px; margin-top: 11px;}
.mz .prob{line-height: 1.725 !important;}
